<?php
require_once __DIR__.'/../includes/bootstrap.php';require_developer();
$q=$pdo->prepare('SELECT p.project_id,p.name FROM projects p WHERE p.user_id=? ORDER BY p.name');$q->execute([current_user()['user_id']]);$projects=$q->fetchAll();
$q=$pdo->prepare('SELECT f.file_id,f.file_name,f.file_type,f.uploaded_at,p.project_id,p.name project_name,(SELECT COUNT(*) FROM dependencies d WHERE d.file_id=f.file_id) dependency_count FROM dependency_files f JOIN projects p ON p.project_id=f.project_id WHERE p.user_id=? ORDER BY f.uploaded_at DESC');$q->execute([current_user()['user_id']]);$files=$q->fetchAll();
page_header('Dependency Scanning');?>
<div class="page-heading"><div><span class="eyebrow">DEVELOPER WORKSPACE</span><h1>Dependency Scanning</h1><p>Upload supported manifests and run or repeat OSV assessments.</p></div></div>
<div class="card mb-4"><div class="card-header"><strong>Uploaded manifests</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Project</th><th>Manifest</th><th>Dependencies</th><th>Uploaded</th><th>Actions</th></tr></thead><tbody>
<?php foreach($files as $f):?><tr><td><?=e($f['project_name'])?></td><td><?=e($f['file_name'])?></td><td><?=number_format((int)$f['dependency_count'])?></td><td><?=e($f['uploaded_at'])?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="<?=e(url('project.php?id='.$f['project_id']))?>">Project</a><form method="post" action="<?=e(url('scan.php'))?>"><?=csrf_field()?><input type="hidden" name="file_id" value="<?=$f['file_id']?>"><button class="btn btn-sm btn-primary">Re-scan</button></form></td></tr><?php endforeach;?><?php if(!$files):?><tr><td colspan="5" class="empty-state">No manifests uploaded yet. Open a project to upload one.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header"><strong>Projects</strong></div><div class="list-group list-group-flush"><?php foreach($projects as $p):?><a class="list-group-item list-group-item-action d-flex justify-content-between" href="<?=e(url('project.php?id='.$p['project_id']))?>"><span><?=e($p['name'])?></span><span class="text-primary">Open project <i class="bi bi-arrow-right"></i></span></a><?php endforeach;?></div></div>
